// font6x8.ts
//
// Independent transcription of components/display/include/font_6x8.h (printable
// ASCII 0x20-0x7E), the exact glyph table display_draw_text/display_draw_text_large
// blit in components/display/display_virt.c. This file is transcribed straight
// from the firmware header, NOT imported from or generated by anything in
// simulator/ui or simulator/gosim: the point of the display-correctness spec is
// an independent ground truth, so a decode/blit bug in the app's framebuffer.ts
// (or a bug in gosim's own font6x8_gen.go) cannot hide behind a shared bug here.
//
// Column-major: 6 bytes per glyph, bit i of a column byte is row i (bit 0 = top),
// matching display_virt.c's `if (bits & (1 << row)) display_pixel(x+col, y+row)`.

export const FONT_FIRST_CODE = 0x20;
